  "sim.poultry-farm.title": "Élevage de volailles",
  "sim.poultry-farm.desc": "Gérez une exploitation de volailles commerciale — alimentation, santé et objectifs de production pour les élevages de poulets de chair et de pondeuses.",
  "sim.cattle-dairy.title": "Bovins & Lait",
