  "sim.sheep-farm.title": "Ferme d’ovins",
  "sim.sheep-farm.desc": "Faites tourner une ferme d’ovins sur des cycles saisonniers : mise-bas, tonte et ventes au marché.",
  "sim.network-noc.title": "Réseau NOC",
  "sim.network-noc.desc": "Agissez en tant qu’ingénieur d’un centre des opérations réseau — diagnostiquez et résolvez des incidents d’infrastructure en temps réel sous pression.",
  "sim.mobile-repair.title": "Atelier de réparation mobile",
  "sim.mobile-repair.desc": "Diagnostiquez et réparez les smartphones — remplacement d’écran, problèmes de batterie et pannes de carte mère.",
  "sim.laptop-repair.title": "Atelier de réparation d’ordinateurs portables",
  "sim.laptop-repair.desc": "Dépannez et réparez les ordinateurs portables : pannes matérielles, problèmes BIOS et remplacement de composants.",
  "sim.perfume-lab.title": "Laboratoire de parfums",
  "sim.perfume-lab.desc": "Mélangez des huiles essentielles et des composés aromatiques pour créer des parfums signature et atteindre des critères de qualité.",
  "sim.detergent-lab.title": "Laboratoire de détergent",
  "sim.detergent-lab.desc": "Formulez des produits de nettoyage — équilibrez les tensioactifs, les charges et les tests de performance dans le budget.",
  "sim.skin-care-lab.title": "Laboratoire de soins de la peau",
  "sim.skin-care-lab.desc": "Développez et testez des formulations cosmétiques, en respectant les normes de sécurité et les objectifs d’efficacité.",
  "sim.woodworking.title": "Atelier de menuiserie",
  "sim.woodworking.desc": "Lancez une boutique de menuiserie sur mesure : planifiez les missions, gérez les matériaux et livrez les meubles à temps et dans le budget.",
  "sim.aluminum-glazing.title": "Aluminium & Vitrage",
  "sim.aluminum-glazing.desc": "Gérez une entreprise de fabrication d’aluminium et de pose de verre, de l’offre à la fin du chantier.",
  "sim.global-kitchen.title": "Cuisine globale",
  "sim.global-kitchen.desc": "Dirigez une cuisine de restaurant : gérez les menus, le personnel, les coûts et la satisfaction client pendant les services.",
  "sim.chocolate-factory.title": "Fabrique de chocolat",
  "sim.chocolate-factory.desc": "Exploitez une usine de confiserie — approvisionnement en cacao, planification de production et contrôle qualité.",
  "sim.solar-energy.title": "Centrale d’énergie solaire",
  "sim.solar-energy.desc": "Concevez et exploitez une installation solaire — dimensionnez les panneaux, gérez l’export vers le réseau et suivez le ROI.",
  "sim.hvac-systems.title": "Systèmes CVC",
  "sim.hvac-systems.desc": "Installez et entretenez des systèmes de chauffage, ventilation et climatisation pour des bâtiments commerciaux.",
  "sim.logistics-supply.title": "Logistique & chaîne d’approvisionnement",
  "sim.logistics-supply.desc": "Optimisez les opérations d’entrepôt, l’acheminement des flottes et les relations avec les fournisseurs pour atteindre les KPI de livraison.",
  "sim.barber-salon.title": "Salon de coiffure",
  "sim.barber-salon.desc": "Gérez un salon de coiffure : rendez-vous, plannings du personnel, tarification et stratégies de fidélisation client.",
  "sim.board-surgeon.title": "Chirurgien de plateau",
  "sim.board-surgeon.desc": "Prenez des décisions chirurgicales à forts enjeux dans un théâtre opératoire simulé — gestion du temps et sécurité du patient.",
  "sim.english-journey.title": "Parcours d’anglais",
  "sim.english-journey.desc": "Guide des apprenants à travers un programme structuré d’anglais, en l’adaptant à différents niveaux de compétence.",
  "sim.music-training.title": "Studio de formation musicale",
  "sim.music-training.desc": "Dirigez une école de musique : planifiez les cours, gérez les instruments et suivez la progression des élèves vers les récitals.",
  "sim.trade-tycoon.title": "Tycoon du commerce",
